@warp k -> casino_neon spawn=stairs
@warp q -> escondite_2 spawn=up
# The elevator panel: a three-row floor list (B1F, B2F, B4F); the row of this floor does nothing.
@var floor 7
@script lift interact
    has_item llave_polea 3
    jv 3 1 ride
    say hide.lift.locked
    say hide.lift.locked2
    end
  ride:
    say hide.lift.on
    say gl.c4a.elev.ask
    elevator floor gl.c4a.floor.b1 gl.c4a.floor.b2 gl.c4a.floor.b4
    jv floor 255 stay
    jv floor 0 stay
    jv floor 1 to1
    jv floor 2 to2
  to1:
    sfx door
    warp escondite_2 spawn=lift
    end
  to2:
    sfx door
    warp escondite_4 spawn=lift
    end
  stay:
    end
@end
